// Synthetic module for the ADOP testbed. Computes a cart total and creates
// a payment intent against the (fake) payments gateway client.

import { paymentsClient } from "./payments-client.js";

const CHECKOUT_DB_CONNECTION = process.env.CHECKOUT_DB_URL ?? "postgres://checkout-db/orders";

/**
 * Validates cart input
 * @param {Object} cart - The cart object to validate
 * @returns {boolean} True if valid
 */
function validateCart(cart) {
  if (!cart || !Array.isArray(cart.items)) {
    throw new Error("Invalid cart format");
  }
  for (const item of cart.items) {
    if (typeof item.price !== "number" || typeof item.qty !== "number") {
      throw new Error("Invalid item format");
    }
  }
  return true;
}

/**
 * Computes a cart total with tax
 * @param {Object} cart - The cart object
 * @returns {number} Rounded total amount
 * @throws {Error} If cart validation fails
 */
export function computeTotal(cart) {
  validateCart(cart);
  const subtotal = cart.items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const tax = subtotal * (cart.taxRate || 0);
  return Math.round((subtotal + tax) * 100) / 100;
}

/**
 * Creates a payment intent for the cart
 * @param {Object} cart - The cart object
 * @returns {Promise<Object>} Payment intent result
 * @throws {Error} If cart validation fails
 */
export async function createPaymentIntent(cart) {
  validateCart(cart);
  const amount = computeTotal(cart);
  return paymentsClient.createIntent({ amount, currency: cart.currency ?? "USD" });
}

// TODO(issue #142): checkout currently shares DB_CONNECTION with the
// fulfillment service. Split into its own database once provisioned.

// Synthetic module for the ADOP testbed. Unrelated to checkout; present so
// the repository has more than one service, matching a realistic monorepo
// slice.

const FULFILLMENT_DB_CONNECTION = process.env.FULFILLMENT_DB_URL ?? "postgres://fulfillment-db/orders";

/**
 * Validates order input
 * @param {Object} order - The order object to validate
 * @returns {boolean} True if valid
 */
function validateOrder(order) {
  if (!order || !order.orderId) {
    throw new Error("Invalid order format");
  }
  return true;
}

/**
 * Schedules a shipment for an order
 * @param {Object} order - The order object
 * @returns {Object} Shipment information
 * @throws {Error} If order validation fails
 */
export function scheduleShipment(order) {
  validateOrder(order);
  return { orderId: order.orderId, status: "scheduled", carrier: "synthetic-carrier" };
}

/**
 * Synthetic stub client for the ADOP testbed.
 * Provides payment intent creation functionality.
 */

/**
 * Creates a payment intent
 * @param {Object} options - Payment intent options
 * @param {number} options.amount - Amount in cents
 * @param {string} [options.currency="USD"] - Currency code
 * @returns {Promise<Object>} Payment intent result
 */
export const paymentsClient = {
  /**
   * Creates a synthetic payment intent
   * @param {Object} options - Payment intent options
   * @param {number} options.amount - Amount in cents
   * @param {string} [options.currency="USD"] - Currency code
   * @returns {Promise<Object>} Payment intent result
   */
  async createIntent({ amount, currency = "USD" }) {
    // In production, this would include error handling and validation
    return {
      id: `pi_fake_${Date.now()}`,
      amount,
      currency,
      status: "requires_confirmation",
    };
  },
};
